def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_test = -1
    for i in range(n-1, -1, -1):
        if my[i] == 'C' and i >= 1 and my[i-1] == 'D' and op[i-1] == 'D':
            last_test = i
            break
    if last_test != -1:
        j = last_test + 1
        if j < n:
            if op[j] == 'D':
                return 'D'
        else:
            return 'C'
    streak = 0
    for i in range(n-1, -1, -1):
        if my[i] == 'D' and op[i] == 'D':
            streak += 1
        else:
            break
    if streak >= 3:
        return 'C'
    last_op = op[-1]
    if last_op == 'C':
        return 'C'
    else:
        if n >= 2:
            my_t2 = my[-2]
            recent_op = op[-3:] if n >= 3 else op
            has_recent_c = any(a == 'C' for a in recent_op)
            if my_t2 == 'D' and has_recent_c:
                return 'C'
        return 'D'
